import {mountQuiz} from './quiz.js?v=12';
import {createViewer} from './house3d.js?v=12';
const app=document.querySelector('#app');const models=await fetch('./data.json').then(r=>{if(!r.ok)throw Error('Каталог недоступен');return r.json()});const tops=['barn_dh27','house_dh64','house_dh93'].map(id=>models.find(m=>m.id===id));const money=n=>new Intl.NumberFormat('ru-RU').format(n)+' ₽';const area=n=>String(n).replace('.',',');const desc=m=>m.description.split(/Площадь застройки/)[0].trim();let viewer=null,carouselViewers=[],scrollHandler=null,page='',selected=1;
const stages=[['Материалы и защита','Закупаем древесину, проверяем качество и влажность — не выше 14%. Затем обрабатываем огне-биозащитным составом методом погружения в ванны.'],['Сборка каркаса пола','Монтаж ветрозащитной мембраны и мелкоячеистой оцинкованной сетки, которая защищает дом от грызунов.'],['Стены и кровля','Сборка каркаса стен и кровли.'],['Коммуникации','Прокладка линий инженерных сетей: электроснабжение, водоснабжение, канализация.'],['Внутренние работы','Укладка минераловатного утеплителя и монтаж ветрозащитной мембраны и пароизоляции.'],['Окна','Установка оконных блоков'],['Отделка','Внутренняя отделка помещений: пол, стены, потолок, сантехника, электрика, межкомнатные двери'],['Фасад','Наружная отделка фасада'],['Кровля','Монтаж кровли. Готовые элементы опускаются сверху и соединяются с каркасом.'],['Готово','Дом занимает своё место на участке. Деревянная терраса, мягкий свет и зелень за окнами. Можно начинать новую жизнь.']];
function card(m){return `<article class="house-card"><button class="card-picture" data-detail="${m.id}" aria-label="Посмотреть ${m.name}"><img src="${m.image}" alt="${m.name} — внешний вид" loading="lazy"><span class="tag">${m.id.startsWith('flat')?'ФЛЭТ':'БАРН'} / ${area(m.area)} М²</span></button><div class="card-info"><div class="card-line"><h3>${m.name}</h3><button class="circle" data-detail="${m.id}" aria-label="Открыть ${m.name}">↗</button></div><p>${desc(m)}</p><div class="card-line"><span class="card-price">${money(m.price)}</span><span class="eyebrow">ПОД КЛЮЧ</span></div></div></article>`}
function home(){app.innerHTML=`<section class="hero"><img src="assets/house_dh93-detail-1.jpg" alt="Деревянный модульный дом DUROV.HOUSE с панорамными окнами и террасой" fetchpriority="high"><div class="hero-content"><span class="eyebrow">СОБСТВЕННОЕ ПРОИЗВОДСТВО · ДОСТАВКА ПО РОССИИ</span><h1>Ближе к природе.<br><em>Ближе к себе.</em></h1><p>Модульный дом, в котором хочется жить.<br>Создаём в цехе. Привозим на ваш участок.<br>Вы наполняете его жизнью.</p><a class="button light" href="#/catalog">Найти свой дом <span>↗</span></a><div class="hero-bottom"><div class="hero-meta"><div><strong>от 30 дней</strong><span>производство дома</span></div><div><strong>14 проектов</strong><span>от 21 до 156 м²</span></div><div><strong>3 дня</strong><span>монтаж на участке*</span></div></div><a class="hero-scroll" href="#idea">ЛИСТАЙТЕ ВНИЗ ↓</a></div></div></section>
<section class="section intro" id="idea"><span class="eyebrow">01 / ДОМ — ЭТО ПРО ВАС</span><div class="intro-copy"><h2>Меньше стройки.<br>Больше жизни.</h2><p>Утренний кофе на террасе. Большой стол для близких. Тишина за окном. Выберите свой сценарий — мы создадим для него пространство.</p><div class="intro-features"><p><strong>Готовая отделка</strong>Можно планировать переезд</p><p><strong>Круглый год</strong>Для дачи и постоянной жизни</p><p><strong>Своё производство</strong>Приходите посмотреть</p></div></div></section>
<section class="section"><div class="section-head"><div><span class="eyebrow">02 / ВАШ БУДУЩИЙ ДОМ</span><h2>Три разных дома.<br>Ваш — один из них.</h2></div><a class="text-link" href="#/catalog">Все 14 проектов и 3D-модели ↗</a></div><div class="cards">${tops.map(card).join('')}</div><div class="catalog-link"><button class="button outline" data-quiz>Не знаете, с чего начать? Подобрать дом ↗</button></div></section>
<section class="production" id="production"><div class="production-heading"><span class="eyebrow">03 / НАШЕ ПРОИЗВОДСТВО</span><h2>Хороший дом.<br>Шаг за шагом.</h2><p>Прокрутите страницу и посмотрите, как он создаётся.</p></div><div class="production-track"><div class="production-sticky"><div class="construction-view" id="construction"><span class="view-label">DUROV.HOUSE / АНАТОМИЯ ДОМА</span><div class="view-controls"><span>↔ Модель можно вращать</span></div></div><div class="step-copy" aria-live="polite"><span class="step-count" id="step-count">01–02 / 11</span><h3 id="step-title">${stages[0][0]}</h3><p id="step-text">${stages[0][1]}</p><div class="step-dots">${stages.map((s,i)=>`<button data-step="${i}" aria-label="Этап ${i===0?'01–02':i+2}: ${s[0]}" ${i===0?'class="active"':''}></button>`).join('')}</div><div class="step-note">Схема показывает последовательность производства.<br>Конструкция и комплектация зависят от проекта.</div></div></div></div></section>
<section class="section split" id="included"><img src="assets/house_dh64-detail-4.jpg" alt="Фасад и крытая терраса дома DUROV.HOUSE" loading="lazy"><div><span class="eyebrow">04 / ВНУТРИ УЖЕ ВСЁ ПРОДУМАНО</span><h2>Дом готов.<br>Осталось ваше.</h2><p>От тёплого контура до розеток и сантехники — изучите стандартную комплектацию.</p><div class="included-list"><details open><summary>Тёплый и защищённый каркас</summary><p>Сухая строганная доска с огне-биозащитной обработкой. Минеральное утепление, пароизоляция и ветрозащита.</p></details><details><summary>Отделка внутри и снаружи</summary><p>Деревянный фасад с защитным покрытием. Внутри — отделка стен и потолка, напольное покрытие. Варианты согласуем под ваш проект.</p></details><details><summary>Окна, двери и инженерные сети</summary><p>Энергоэффективные стеклопакеты, межкомнатные двери, электрика, водоснабжение, отопительные конвекторы и вентиляция.</p></details><details><summary>Готовый санузел</summary><p>Сантехника, раковина с тумбой, смесители, водонагреватель и вывод под стиральную машину. Детали комплектации уточняются в договоре.</p></details></div><p class="footnote">Стоимость доставки, фундамента и дополнительные опции рассчитываются для вашего участка отдельно.</p></div></section>
<section class="section visit split"><div><span class="eyebrow">05 / МОЖНО УВИДЕТЬ СВОИМИ ГЛАЗАМИ</span><h2>Загляните туда,<br>где рождается<br>ваш дом.</h2><p>Мы работаем в закрытом цехе в Воронежской области. Приглашаем познакомиться с командой, пройти по этапам производства и посмотреть качество в деталях.</p><a class="button light" href="https://t.me/durov_house_com" target="_blank" rel="noopener">Записаться на экскурсию ↗</a></div><img src="assets/production-IMG_0459.jpg" alt="Модульный дом на собственном производстве DUROV.HOUSE" loading="lazy"></section>
<section class="section"><div class="faq"><span class="eyebrow">06 / ПЕРЕД ПЕРВЫМ ШАГОМ</span><h2>Хорошие вопросы.</h2>${[['Можно ли жить в доме зимой?','Да. Дома рассчитаны на круглогодичное проживание. В конструкции используется плитная минеральная вата, отопление — электрическими конвекторами, в санузле предусмотрен тёплый пол.'],['Сколько времени займёт производство?','На исходном сайте указан срок от одного до трёх месяцев. Точный срок зависит от модели и комплектации и фиксируется при согласовании проекта.'],['Что нужно подготовить на участке?','Подъезд для доставки и установки модулей, фундамент и точки подключения коммуникаций. Обычно используется свайный фундамент. Условия проверяются для конкретного участка.'],['Можно ли изменить планировку?','Можно обсудить индивидуальный проект и дополнительные опции. Начните с теста подбора или расскажите о пожеланиях нашей команде.'],['Можно ли купить дом в ипотеку?','Компания работает с ипотечными программами банков-партнёров. Доступность программы, ставка и первоначальный взнос уточняются при обращении.'],['Где посмотреть построенные дома?','Посмотрите завершённые проекты на действующем сайте или договоритесь с командой о просмотре. <a class="text-link" href="https://durov.house/completed_projects" target="_blank" rel="noopener">Завершённые проекты ↗</a>']].map(([q,a])=>`<details><summary>${q}</summary><p>${a}</p></details>`).join('')}<p class="footnote">* Срок монтажа зависит от проекта и готовности участка. Цены и комплектацию подтвердит менеджер. Не является публичной офертой.</p></div></section>`;
viewer=createViewer(document.querySelector('#construction'),{construction:true});let last=-1;scrollHandler=()=>{const track=document.querySelector('.production-track');if(!track)return;const top=parseFloat(getComputedStyle(document.querySelector('header')).height);const v=Math.max(0,Math.min(9.999,(top-track.getBoundingClientRect().top)/(track.offsetHeight-(innerHeight-top))*11));viewer?.setStage(v);const n=Math.min(9,Math.floor(v));if(n!==last){last=n;document.querySelector('#step-count').textContent=(n===0?'01–02':String(n+2).padStart(2,'0'))+' / 11';document.querySelector('#step-title').textContent=stages[n][0];document.querySelector('#step-text').textContent=stages[n][1];document.querySelectorAll('[data-step]').forEach((b,i)=>{b.classList.toggle('active',i===n);b.setAttribute('aria-current',i===n?'step':'false')})}};addEventListener('scroll',scrollHandler,{passive:true});scrollHandler();document.querySelectorAll('[data-step]').forEach(b=>b.onclick=()=>{const track=document.querySelector('.production-track'),top=document.querySelector('header').offsetHeight;window.scrollTo({top:scrollY+track.getBoundingClientRect().top-top+(track.offsetHeight-(innerHeight-top))*(Number(b.dataset.step)+.4)/11,behavior:'instant'})});}
function catalog(){app.innerHTML=`<section class="catalog-hero"><span class="eyebrow">КОЛЛЕКЦИЯ DUROV.HOUSE</span><h1>Найдите своё место.</h1><p>14 проектов. Два характера. Один — ваш.</p><div class="section-head" style="margin-top:45px;margin-bottom:0"><span class="eyebrow">ТОПЫ ПРОДАЖ / ИССЛЕДУЙТЕ В 3D</span><span class="eyebrow">01 — 03</span></div><div class="character-carousel" aria-label="Три самых продаваемых дома">${tops.map((m,i)=>`<article class="character-card" data-character="${i}"><button class="character-select" data-model="${i}" aria-label="Выбрать ${m.name}"><span>${m.name}</span><small>${area(m.area)} м²</small></button><div class="character-model" id="model-${i}"><span class="model-rotate-hint"><span class="hint-long">↔ Вращайте мышью или пальцем</span><span class="hint-short">↔ Вращайте</span></span><button class="model-interior" data-interior="${i}" aria-pressed="false">Интерьер ↗</button></div><div class="character-info"><span class="eyebrow">${i===0?'КОМПАКТНЫЙ':i===1?'СЕМЕЙНЫЙ':'ПРОСТОРНЫЙ'}</span><h2>${m.name}</h2><p>${area(m.area)} м² · ${money(m.price)}</p><button class="button" data-detail="${m.id}">Планировка и детали ↗</button></div></article>`).join('')}</div><div class="carousel-navigation"><button class="circle" id="previous-model" aria-label="Предыдущий дом">←</button><span class="eyebrow" id="carousel-position"></span><button class="circle" id="next-model" aria-label="Следующий дом">→</button></div><p class="footnote">3D-визуализации восстановлены по опубликованным фотографиям и планировкам. Материалы и детали уточняются при согласовании проекта.</p></section><section class="section" id="all-models"><div class="section-head"><div><span class="eyebrow">АРХИТЕКТУРА ДЛЯ ВАШЕЙ ЖИЗНИ</span><h2>Все дома.</h2></div><button class="button outline" data-quiz>Помогите мне выбрать ↗</button></div><div class="filters"><div class="filter-types" role="group" aria-label="Тип архитектуры"><button class="active" data-type="all">Все проекты</button><button data-type="barn">Барн</button><button data-type="flat">Флэт</button></div><select id="area-filter" aria-label="Площадь дома"><option value="all">Любая площадь</option><option value="small">До 40 м²</option><option value="medium">40–80 м²</option><option value="large">Больше 80 м²</option></select><select id="sort" aria-label="Сортировка"><option value="default">По коллекции</option><option value="price-up">Сначала дешевле</option><option value="price-down">Сначала дороже</option><option value="area">По площади</option></select></div><p class="catalog-count" id="catalog-count"></p><div class="cards catalog-grid" id="catalog-grid"></div><p class="footnote">Указана площадь застройки. Планировки и полезную площадь смотрите в карточке дома. Стоимость приведена по действующему сайту и уточняется при заказе.</p></section>`;
carouselViewers=tops.map((m,i)=>createViewer(document.querySelector('#model-'+i),{id:m.id}));document.querySelectorAll('[data-interior]').forEach(b=>b.onclick=()=>{const on=b.getAttribute('aria-pressed')!=='true';b.setAttribute('aria-pressed',String(on));b.textContent=on?'Снаружи ↗':'Интерьер ↗';carouselViewers[Number(b.dataset.interior)]?.setInterior(on)});function updateModel(){document.querySelectorAll('[data-character]').forEach((card,i)=>{const position=i===selected?'center':i===(selected+2)%3?'left':'right';card.dataset.position=position;carouselViewers[i]?.setEmphasis(position);card.querySelector('[data-model]').setAttribute('aria-pressed',String(i===selected))});document.querySelector('#carousel-position').textContent='0'+(selected+1)+' / 03';}document.querySelector('#previous-model').onclick=()=>{selected=(selected+2)%3;updateModel()};document.querySelector('#next-model').onclick=()=>{selected=(selected+1)%3;updateModel()};document.querySelectorAll('[data-model]').forEach(b=>b.onclick=()=>{selected=Number(b.dataset.model);updateModel()});updateModel();let type='all';function filter(){const af=document.querySelector('#area-filter').value,sort=document.querySelector('#sort').value;let list=models.filter(m=>(type==='all'||(type==='flat'?m.id.startsWith('flat'):!m.id.startsWith('flat')))&&(af==='all'||af==='small'&&m.area<40||af==='medium'&&m.area>=40&&m.area<=80||af==='large'&&m.area>80));if(sort==='price-up')list.sort((a,b)=>a.price-b.price);if(sort==='price-down')list.sort((a,b)=>b.price-a.price);if(sort==='area')list.sort((a,b)=>a.area-b.area);document.querySelector('#catalog-grid').innerHTML=list.length?list.map(card).join(''):'<div class="empty">Для этих параметров нет проектов. Измените площадь или тип дома.</div>';document.querySelector('#catalog-count').textContent=`Показано ${list.length} из ${models.length} проектов`;document.querySelectorAll('[data-type]').forEach(b=>{b.classList.toggle('active',b.dataset.type===type);b.setAttribute('aria-pressed',String(b.dataset.type===type))})}document.querySelectorAll('[data-type]').forEach(b=>b.onclick=()=>{type=b.dataset.type;filter()});document.querySelector('#area-filter').onchange=filter;document.querySelector('#sort').onchange=filter;filter();}
function detail(id){const m=models.find(x=>x.id===id);if(!m)return;const gallery=(m.gallery||[]).filter(p=>p!==m.plan);document.querySelector('#detail-content').innerHTML=`<div class="detail-top"><img src="${m.image}" alt="${m.name}"><div><span class="eyebrow">ВАШЕ ПРОСТРАНСТВО ДЛЯ ЖИЗНИ</span><h2>${m.name}</h2><p>${desc(m)}</p><div class="detail-stats"><div><strong>${area(m.area)} м²</strong><small>площадь застройки</small></div></div><h3>${money(m.price)}</h3><a class="button" href="https://t.me/durov_house_com" target="_blank" rel="noopener">Обсудить этот проект ↗</a></div></div>${m.plan?`<div class="plan"><span class="eyebrow">ОРИГИНАЛЬНАЯ ПЛАНИРОВКА</span><a href="${m.plan}" target="_blank" rel="noopener" aria-label="Открыть планировку в полном размере"><img src="${m.plan}" alt="Чертёж планировки ${m.name}"></a></div>`:''}<div class="detail-gallery">${gallery.slice(0,4).map(p=>`<img loading="lazy" src="${p}" alt="${m.name}: ракурс и детали">`).join('')}</div><p class="footnote">Изображения и чертежи с действующего сайта DUROV.HOUSE. Финальная комплектация, стоимость фундамента и доставки согласуются отдельно. <a class="text-link" href="${m.url}" target="_blank" rel="noopener">Исходная страница проекта ↗</a></p>`;openDialog(document.querySelector('#detail'))}
let lastFocus;function openDialog(d){lastFocus=document.activeElement;d.showModal();document.body.classList.add('no-scroll')}document.querySelectorAll('dialog').forEach(d=>{d.querySelector('.close').onclick=()=>d.close();d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}});d.addEventListener('close',()=>{document.body.classList.remove('no-scroll');lastFocus?.focus()})});document.addEventListener('click',e=>{const quiz=e.target.closest('[data-quiz]');if(quiz){openDialog(document.querySelector('#quiz'))}const c=e.target.closest('[data-detail]');if(c)detail(c.dataset.detail);if(e.target.closest('nav a')){document.querySelector('header').classList.remove('open');document.querySelector('.menu').setAttribute('aria-expanded','false')}});document.querySelector('.menu').onclick=()=>{const h=document.querySelector('header');h.classList.toggle('open');document.querySelector('.menu').setAttribute('aria-expanded',String(h.classList.contains('open')))};
function route(){const hash=location.hash;const next=hash.startsWith('#/catalog')?'catalog':'home';if(page!==next){viewer?.destroy();viewer=null;carouselViewers.forEach(v=>v.destroy());carouselViewers=[];if(scrollHandler){removeEventListener('scroll',scrollHandler);scrollHandler=null}page=next;next==='catalog'?catalog():home();document.title=next==='catalog'?'Каталог домов — DUROV.HOUSE':'DUROV.HOUSE — место для вашей жизни';if(hash==='#/'||next==='catalog')window.scrollTo({top:0,behavior:'instant'})}if(hash==='#/')window.scrollTo({top:0,behavior:'instant'});if(hash&&!hash.startsWith('#/'))requestAnimationFrame(()=>document.querySelector(hash)?.scrollIntoView({behavior:'instant'}))}addEventListener('hashchange',route);mountQuiz(document.querySelector('#quiz-content'),models,{onDetail(id){document.querySelector('#quiz').close();detail(id)}});route();document.addEventListener('click',e=>{const a=e.target.closest('a[href^="#"]');if(a&&a.hash===location.hash){e.preventDefault();route()}});
